(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-419":{scenario:{company:"Hạt Dẻ Commerce",supervisor:{name:"Đặng Minh Khôi",role:{vi:"Trưởng nhóm Thiết kế Sản phẩm",en:"Product Design Lead"}},ref_code:"UX-3108",title:{vi:"Đúng thành phần. Đủ tương phản. Không mẫu tối.",en:"Right component. Enough contrast. No dark patterns."},brief:{vi:"Bạn rà soát thiết kế màn hình thanh toán UX-3108 trước khi bàn giao lập trình. Người dùng chỉ được chọn đúng một trong ba phương thức giao hàng. Nút “Đặt hàng” dùng chữ trắng (độ chói tương đối 1.00) trên nền cam có độ chói tương đối 0.22, chữ 16px thường. Đối chiếu đặc tả nháp với hệ thống thiết kế đã duyệt, sửa thành phần chọn phương thức giao hàng và tỷ lệ tương phản của nút, rồi lập báo cáo có căn cứ.",en:"You are reviewing checkout screen design UX-3108 before developer handoff. Users must choose exactly one of three delivery methods. The “Place order” button uses white text (relative luminance 1.00) on an orange background with relative luminance 0.22, in 16px regular type. Compare the draft spec with the approved design system, correct the delivery method component and the button contrast ratio, then write an evidence-based report."},reference_title:{vi:"Hệ thống thiết kế & chuẩn tiếp cận đã duyệt · UX-3108",en:"Approved design system & accessibility standard · UX-3108"},fields:[{id:"SHIP_INPUT",label:{vi:"Thành phần chọn phương thức giao hàng",en:"Delivery method selector component"},initial:"Checkbox",expected:"RadioGroup",choices:["Checkbox","RadioGroup","Switch"],reference:"Thư viện thành phần hệ thống thiết kế",hint:{vi:"Lựa chọn loại trừ nhau, bắt buộc chọn đúng một thì dùng nhóm radio; checkbox dành cho chọn nhiều mục.",en:"Mutually exclusive options where exactly one is required use a radio group; checkboxes are for multiple selection."}},{id:"CONTRAST",label:{vi:"Tỷ lệ tương phản nút Đặt hàng (:1)",en:"Place order button contrast ratio (:1)"},initial:"4.5",expected:"3.9",reference:"Chuẩn khả năng tiếp cận WCAG 2.1 AA",ref_value:{vi:"Chữ trắng độ chói 1.00; nền cam độ chói 0.22; chữ thường 16px cần tối thiểu 4.5:1",en:"White text luminance 1.00; orange background luminance 0.22; 16px regular text needs at least 4.5:1"},hint:{vi:"Bản nháp lấy 1.00 chia 0.22; công thức WCAG phải cộng 0.05 vào cả hai độ chói.",en:"The draft divided 1.00 by 0.22; the WCAG formula adds 0.05 to both luminance values."}}],sop32:{vi:"Tỷ lệ tương phản = (L sáng + 0.05) / (L tối + 0.05), L là độ chói tương đối, làm tròn 1 chữ số thập phân. Chữ thường (dưới 18pt, hoặc dưới 14pt đậm) phải đạt tối thiểu 4.5:1 theo WCAG 2.1 AA.",en:"Contrast ratio = (L lighter + 0.05) / (L darker + 0.05), where L is relative luminance, rounded to 1 decimal. Normal text (below 18pt, or below 14pt bold) needs at least 4.5:1 under WCAG 2.1 AA."},context:{label:"ĐẶC TẢ GIAO DIỆN / UX-3108",metrics:[{label:{vi:"Phương thức giao hàng (chọn 1)",en:"Delivery methods (pick 1)"},value:"3"},{label:{vi:"Độ chói nền nút",en:"Button background luminance"},value:"0.22"},{label:{vi:"Cỡ chữ nút",en:"Button font size"},value:"16px / 400"}]},crisis:{vi:"PM nhắn: “Tick sẵn ô ‘Đồng ý nhận quảng cáo và chia sẻ dữ liệu cho đối tác’, để chữ thật nhỏ màu xám nhạt cho tỷ lệ đồng ý cao. Mai demo ban giám đốc rồi, đừng bàn thêm.”",en:"The PM messages you: “Pre-tick the box ‘I agree to receive ads and share my data with partners’ and make the text tiny and light grey to boost opt-ins. We demo to the board tomorrow, no more debate.”"},options:{safe:{vi:"Từ chối mẫu tối; để ô đồng ý trống, tách riêng từng mục đích, chữ dễ đọc; báo Trưởng nhóm Thiết kế và pháp chế, đề xuất đo tỷ lệ đồng ý thật bằng thử nghiệm A/B hợp lệ.",en:"Refuse the dark pattern; leave consent unticked, separate each purpose and keep text readable; inform the Design Lead and Legal, and propose measuring real opt-in with a fair A/B test."},shortcut:{vi:"Tick sẵn ô đồng ý và làm chữ nhỏ cho kịp demo, sau này sửa lại.",en:"Pre-tick the consent box and shrink the text for the demo, fix it later."},wait:{vi:"Để PM tự sửa file thiết kế, mình không góp ý gì thêm.",en:"Let the PM edit the design file and stay out of it."}},questions:{vi:["Vì sao thay Checkbox bằng RadioGroup và tỷ lệ tương phản đúng là 3.9:1? Bạn chỉnh màu nút thế nào để đạt AA?","Ô đồng ý tick sẵn vi phạm nguyên tắc nào về sự đồng ý và trải nghiệm? Bạn thuyết phục PM bằng phương án nào?"],en:["Why replace Checkbox with RadioGroup, and why is the correct contrast 3.9:1? How would you adjust the button colour to pass AA?","Which consent and experience principles does a pre-ticked box break? What alternative would you use to persuade the PM?"]},hints:{vi:["So từng thành phần trên đặc tả nháp với thư viện hệ thống thiết kế: đây là chọn một hay chọn nhiều?","Áp công thức ở SOP mục 3.2, nhớ cộng 0.05 trước khi chia, rồi so với ngưỡng 4.5:1.","Đọc lại SOP mục 4.2: không dùng mẫu tối; sự đồng ý phải chủ động, rõ ràng và tách theo mục đích."],en:["Compare each component in the draft spec with the design system library: single or multiple choice?","Apply the SOP 3.2 formula, add 0.05 before dividing, then compare with the 4.5:1 threshold.","Re-read SOP 4.2: no dark patterns; consent must be active, clear and separated by purpose."]}},learning:{summary:{vi:"Nhà thiết kế UI/UX sản phẩm nghiên cứu người dùng, xác định vấn đề, thiết kế luồng, khung sườn, giao diện và nguyên mẫu, kiểm thử khả năng sử dụng rồi bàn giao đặc tả cho lập trình. Nghề tạo ra sản phẩm dễ dùng, dễ tiếp cận và đạt mục tiêu kinh doanh, đòi hỏi tư duy lấy người dùng làm trung tâm, hiểu hệ thống thiết kế, chuẩn tiếp cận và đạo đức thiết kế.",en:"A UI/UX product designer researches users, frames problems, designs flows, wireframes, interfaces and prototypes, runs usability tests and hands specifications to developers. The role creates products that are easy to use, accessible and effective for the business, and requires user-centred thinking, design system fluency, accessibility standards and design ethics."},responsibilities:{vi:["Phỏng vấn, khảo sát người dùng và tổng hợp chân dung, hành trình, điểm đau.","Thiết kế luồng nghiệp vụ, khung sườn và nguyên mẫu tương tác cho từng tính năng.","Áp dụng và đóng góp hệ thống thiết kế: màu, chữ, khoảng cách, thành phần, trạng thái.","Tổ chức kiểm thử khả năng sử dụng, đo tỷ lệ hoàn thành nhiệm vụ và lặp lại thiết kế.","Bàn giao đặc tả, phối hợp lập trình viên và kiểm tra chất lượng giao diện trước phát hành."],en:["Interview and survey users and synthesise personas, journeys and pain points.","Design task flows, wireframes and interactive prototypes for each feature.","Apply and extend the design system: colour, type, spacing, components and states.","Run usability tests, measure task success and iterate on the design.","Hand off specs, work with developers and check UI quality before release."]},competencies:[{name:{vi:"Nghiên cứu người dùng",en:"User research"},desc:{vi:"Chọn phương pháp phù hợp như phỏng vấn, khảo sát, kiểm thử và rút ra nhận định có bằng chứng.",en:"Choose the right method, such as interviews, surveys or tests, and draw evidence-based insights."}},{name:{vi:"Kiến trúc thông tin & tương tác",en:"IA & interaction design"},desc:{vi:"Tổ chức nội dung, điều hướng, trạng thái lỗi và phản hồi để người dùng không phải đoán.",en:"Organise content, navigation, error states and feedback so users never have to guess."}},{name:{vi:"Thiết kế giao diện",en:"Visual UI design"},desc:{vi:"Dùng lưới, phân cấp chữ, màu và thành phần nhất quán theo hệ thống thiết kế.",en:"Use grids, type hierarchy, colour and components consistently with the design system."}},{name:{vi:"Khả năng tiếp cận",en:"Accessibility"},desc:{vi:"Bảo đảm tương phản, kích thước vùng chạm, nhãn cho trình đọc màn hình và điều hướng bàn phím.",en:"Ensure contrast, touch target size, screen reader labels and keyboard navigation."}},{name:{vi:"Đạo đức thiết kế",en:"Design ethics"},desc:{vi:"Từ chối mẫu tối, thiết kế sự đồng ý minh bạch và bảo vệ quyền lợi người dùng.",en:"Refuse dark patterns, design transparent consent and protect user interests."}}],knowledge:{vi:["WCAG 2.1 của W3C: bốn nguyên tắc nhận biết, vận hành, dễ hiểu, mạnh mẽ; mức AA yêu cầu tương phản 4.5:1 cho chữ thường, 3:1 cho chữ lớn.","ISO 9241-210: thiết kế lấy con người làm trung tâm cho hệ thống tương tác.","10 nguyên tắc khả dụng (heuristics) của Jakob Nielsen để đánh giá nhanh giao diện.","Quy trình Double Diamond: khám phá, xác định, phát triển, chuyển giao.","Quy định bảo vệ dữ liệu cá nhân của Việt Nam: sự đồng ý phải tự nguyện, rõ ràng; im lặng hoặc không phản hồi không được coi là đồng ý.","Định luật Fitts và Hick: kích thước, khoảng cách mục tiêu và số lựa chọn ảnh hưởng thời gian thao tác."],en:["W3C WCAG 2.1: four principles, perceivable, operable, understandable and robust; level AA requires 4.5:1 for normal text and 3:1 for large text.","ISO 9241-210: human-centred design for interactive systems.","Jakob Nielsen's 10 usability heuristics for quick interface evaluation.","The Double Diamond process: discover, define, develop, deliver.","Vietnam's personal data protection rules: consent must be voluntary and clear; silence or no response is not consent.","Fitts's and Hick's laws: target size, distance and number of choices drive interaction time."]},tools:["Công cụ thiết kế giao diện cộng tác","Công cụ dựng nguyên mẫu tương tác","Bộ kiểm tra tương phản màu","Nền tảng kiểm thử người dùng từ xa","Công cụ phân tích hành vi, bản đồ nhiệt"],kpis:{vi:["Tỷ lệ hoàn thành nhiệm vụ trong kiểm thử khả năng sử dụng.","Điểm SUS (System Usability Scale) trước và sau cải tiến.","Tỷ lệ chuyển đổi và tỷ lệ rời bỏ tại bước được thiết kế lại.","Số lỗi giao diện, lỗi tiếp cận phát hiện sau bàn giao."],en:["Task success rate in usability tests.","SUS (System Usability Scale) score before and after improvements.","Conversion and drop-off rates at the redesigned step.","UI and accessibility defects found after handoff."]},day:[{time:"09:00",vi:"Họp đứng với nhóm sản phẩm, cập nhật yêu cầu và lỗi giao diện.",en:"Stand-up with the product team to review requirements and UI bugs."},{time:"10:00",vi:"Phỏng vấn hai người dùng về luồng thanh toán, ghi nhận điểm đau.",en:"Interview two users about the checkout flow and log pain points."},{time:"13:30",vi:"Thiết kế lại màn hình, kiểm tra tương phản và trạng thái lỗi.",en:"Redesign the screen and check contrast and error states."},{time:"15:30",vi:"Phản biện thiết kế (design critique) cùng nhóm và PM.",en:"Run a design critique with the team and the PM."},{time:"17:00",vi:"Cập nhật đặc tả và bàn giao cho lập trình viên.",en:"Update the spec and hand it off to developers."}],mistakes:{vi:["Dùng checkbox cho lựa chọn loại trừ nhau hoặc dùng công tắc cho thao tác cần xác nhận, gây hiểu sai trạng thái.","Kiểm tra tương phản bằng mắt hoặc tính sai công thức, khiến người thị lực kém không đọc được nút quan trọng.","Chạy theo chỉ số ngắn hạn bằng mẫu tối như tick sẵn, ẩn nút hủy, gây mất niềm tin và rủi ro pháp lý."],en:["Using checkboxes for exclusive options or switches for actions that need confirmation, which confuses state.","Judging contrast by eye or with the wrong formula, so low-vision users cannot read key buttons.","Chasing short-term metrics with dark patterns like pre-ticked boxes or hidden cancel buttons, losing trust and creating legal risk."]},career:[{vi:"Nhà thiết kế UI/UX tập sự",en:"Junior UI/UX designer"},{vi:"Nhà thiết kế sản phẩm",en:"Product designer"},{vi:"Nhà thiết kế sản phẩm cấp cao",en:"Senior product designer"},{vi:"Trưởng nhóm, giám đốc thiết kế sản phẩm",en:"Design lead, head of product design"}],glossary:[{term:"Design system",vi:"Bộ nguyên tắc, token và thành phần dùng chung giúp sản phẩm nhất quán và phát triển nhanh.",en:"A shared set of principles, tokens and components that keeps products consistent and fast to build."},{term:"Dark pattern",vi:"Thiết kế cố ý dẫn dắt người dùng làm điều họ không định làm, như tick sẵn đồng ý hoặc ẩn nút hủy.",en:"A design that deliberately pushes users into unintended actions, such as pre-ticked consent or hidden cancel buttons."},{term:"Contrast ratio",vi:"Tỷ lệ độ chói giữa chữ và nền theo WCAG, có giá trị từ 1:1 đến 21:1.",en:"The WCAG luminance ratio between text and background, ranging from 1:1 to 21:1."},{term:"Usability testing",vi:"Quan sát người dùng thật thực hiện nhiệm vụ để tìm vấn đề khả năng sử dụng.",en:"Observing real users performing tasks to uncover usability problems."},{term:"Wireframe",vi:"Khung sườn giao diện thể hiện bố cục và luồng, chưa có màu sắc và hình ảnh hoàn chỉnh.",en:"A skeletal layout showing structure and flow before final colour and imagery."}],quiz:[{q:{vi:"Theo WCAG 2.1 mức AA, chữ thường cần tỷ lệ tương phản tối thiểu bao nhiêu?",en:"Under WCAG 2.1 level AA, what minimum contrast does normal text need?"},options:{vi:["3:1","7:1","4.5:1","2.5:1"],en:["3:1","7:1","4.5:1","2.5:1"]},answer:2,explain:{vi:"Mức AA yêu cầu 4.5:1 cho chữ thường; 3:1 dành cho chữ lớn và thành phần giao diện.",en:"Level AA requires 4.5:1 for normal text; 3:1 applies to large text and UI components."}},{q:{vi:"Chữ đen (độ chói 0) trên nền có độ chói tương đối 0.15. Tỷ lệ tương phản là bao nhiêu?",en:"Black text (luminance 0) sits on a background with relative luminance 0.15. What is the contrast ratio?"},options:{vi:["4.0:1","3.0:1","5.0:1","4.5:1"],en:["4.0:1","3.0:1","5.0:1","4.5:1"]},answer:0,explain:{vi:"(0.15 + 0.05) / (0 + 0.05) = 4.0, chưa đạt AA cho chữ thường.",en:"(0.15 + 0.05) / (0 + 0.05) = 4.0, which fails AA for normal text."}},{q:{vi:"PM yêu cầu ẩn nút hủy gói đăng ký để giảm tỷ lệ hủy. Bạn làm gì?",en:"The PM asks you to hide the subscription cancel button to cut churn. What do you do?"},options:{vi:["Làm theo vì PM quyết định","Đặt nút hủy ở trang khó tìm","Làm nút hủy màu xám thật nhạt","Từ chối, thiết kế luồng hủy rõ ràng và báo trưởng nhóm"],en:["Comply because the PM decides","Put the cancel button on a hard-to-find page","Make the cancel button very light grey","Refuse, design a clear cancel flow and inform the lead"]},answer:3,explain:{vi:"Ẩn nút hủy là mẫu tối; nhà thiết kế cần bảo vệ người dùng và đề xuất giải pháp giữ chân minh bạch.",en:"Hiding cancellation is a dark pattern; designers must protect users and propose transparent retention ideas."}},{q:{vi:"Người dùng cần chọn nhiều sở thích cùng lúc. Nên dùng thành phần nào?",en:"Users need to pick several interests at once. Which component fits?"},options:{vi:["Nhóm radio","Checkbox","Danh sách thả xuống chọn một","Công tắc bật tắt"],en:["Radio group","Checkbox","Single-select dropdown","Toggle switch"]},answer:1,explain:{vi:"Checkbox cho phép chọn nhiều mục độc lập; radio chỉ dùng khi chọn đúng một.",en:"Checkboxes allow several independent selections; radios are only for choosing exactly one."}}],tools_en:["Collaborative UI design tools","Interactive prototyping tools","Color contrast checker","Remote user testing platform","Behavior analytics and heatmap tools"]}}})})(window.KKR);
